import{_ as e,H as p,f as l,i as t}from"./chunks/framework.BH2BK_3i.js";const u=JSON.parse('{"title":"结束语 | 携手同行，踏上通往AGI的新征程","description":"","frontmatter":{},"headers":[{"level":2,"title":"课程背后的设计思路","slug":"课程背后的设计思路","link":"#课程背后的设计思路","children":[{"level":3,"title":"一门课的生命周期有多长？","slug":"一门课的生命周期有多长","link":"#一门课的生命周期有多长","children":[]},{"level":3,"title":"产品经理究竟应该学什么？","slug":"产品经理究竟应该学什么","link":"#产品经理究竟应该学什么","children":[]}]},{"level":2,"title":"把课程当做产品来做","slug":"把课程当做产品来做","link":"#把课程当做产品来做","children":[]}],"relativePath":"成为AGI产品经理/结束语｜携手同行，踏上通往AGI的新征程.md","filePath":"成为AGI产品经理/结束语｜携手同行，踏上通往AGI的新征程.md","lastUpdated":1795557342000}'),a={name:"成为AGI产品经理/结束语｜携手同行，踏上通往AGI的新征程.md"};function n(s,i,r,o,A,E){return p(),l("div",null,[...i[0]||(i[0]=[t('<h1 id="结束语-携手同行-踏上通往agi的新征程" tabindex="-1">结束语 | 携手同行，踏上通往AGI的新征程 <a class="header-anchor" href="#结束语-携手同行-踏上通往agi的新征程" aria-label="Permalink to &quot;结束语 | 携手同行，踏上通往AGI的新征程&quot;">​</a></h1><p>你好，我是产品二姐。</p><p>感谢你的到来，和我一起为这门课画上一个圆满的句号，请你先为自己鼓个掌来庆祝一下。</p><p>在这个即将结束的时刻，回顾过去几个月的经历，一幕幕的场景像电影一样在我脑海中快速闪过，比如：</p><ul><li><p>第一次和编辑老师对目录，被那么多的意见冲击，甚至曾想过放弃。</p></li><li><p>第一次录样板音频，3 分钟的文字我在凌晨一点的夜晚录了二十几遍。</p></li><li><p>第一次在国庆节连续加了五天班，在朋友圈的旅游攻略中，默默在自习室赶稿。</p></li><li><p>第一次收到同学好评时有点小小的得意和沾沾自喜。</p></li><li><p>……</p></li></ul><p>想到这里，我也不禁想要为自己鼓掌庆祝一下。</p><p>在课程最后，和你坐下来提起这些心路历程的时候，我也想聊聊这门课程背后的设计思路，以及一个产品经理对一门课程的理解。</p><h2 id="课程背后的设计思路" tabindex="-1">课程背后的设计思路 <a class="header-anchor" href="#课程背后的设计思路" aria-label="Permalink to &quot;课程背后的设计思路&quot;">​</a></h2><p>其实，从最初开始写课程大纲的时候，我就一直在问自己两个问题：</p><ol><li><p>这门课能活多久？</p></li><li><p>产品经理在 AI 的浪潮中究竟应该学什么？</p></li></ol><h3 id="一门课的生命周期有多长" tabindex="-1">一门课的生命周期有多长？ <a class="header-anchor" href="#一门课的生命周期有多长" aria-label="Permalink to &quot;一门课的生命周期有多长？&quot;">​</a></h3><p>过去的一年，AI 可以说是一周一个小变化，一月一个大变化。那么，到底什么样的课程能在这种变化之中维持长期的生命力呢？</p><p>在媒体狂轰乱炸的嘈杂声中，我开始冷静地思考这门课程内容之中“变与不变”。变的部分是希望能跟上时代，为大家呈现出不同的内容；不变的部分是希望这门课能保持本色，不做内容的墙头草。</p><p>不变的东西有哪些呢？</p><ul><li><p>算法的基本原理逃不了神经网络。</p></li><li><p>算力对 GPU 并行计算的要求不会变。</p></li><li><p>数据定义软件是不可撼动的趋势，不会变。</p></li><li><p>AI 软件产品的结构不会改变。</p></li><li><p>构建应用的技术不会变，无论什么产品，总离不开 RAG、提示词工程和微调技术。</p></li></ul><p>那么变化的东西又有些什么呢，我列出了一些示例，比如：</p><ul><li><p>我们未来构建应用的方式可能会变：到底是用 Dify、Coze 这种低代码，还是用 LangChain这种代码框架？</p></li><li><p>应用的使用场景可能会变：到底是知识场景的问答会更有前景，还是执行类场景中的 Agent更有想象力，Agent 到底能实现吗？</p></li><li><p>用户的体验方式可能会变：ChatBot 到底能有多大的扩展空间？传统的 GUI 会被抛弃吗？GUI in LUI 会成为主流吗？</p></li><li><p>产研协作的方式可能会变：产品经理和开发这两个职位的界限越来越模糊，会不会诞生新的角色呢？</p></li><li><p>商业化的路径可能会变：就像在互联网早期我们不会想到广告会怎么变，在 AI 的早期，我们能预测到 AI native 的商业模式吗？</p></li></ul><p>在列出这些尚未定型的变化后，我就开始问自己：未来这些可能会变得完全不一样，到底要不要写，写了会不会引起争议，会不会被别人说我在胡说八道？</p><p>在我犹豫不决的时候，想起 10 年前的一段经历。当时我以企业讲师的身份在北京交通大学给大三学生们上课，在学期末尾的学生反馈问卷中，我收到这样一个反馈：“老师的课能让我们听到不一样的东西，和出版社编的教材不一样，特别有趣，能让我们感受到真正的企业是怎么做事情的。”</p><p>想到这里，我下定主意：“既然要写，那就应该写点不一样的东西！” 。</p><p>于是我便放下了心中那个“成为权威”的包袱，转而将这门课视为“一次全新的探索之旅”。所以，你也许会在课程中看到一些尚未形成共识的看法，也许还有一些刚刚产生萌芽的产品形态，这些看法或许不能让你“拿来即用”，但我相信它能激发你产生更多的思路去尝试与探索。</p><p>我希望在五年之后，当再有新晋的产品经理再来看这门课时，能感受到“先行者们”在新技术面前的勇敢尝试，而这又何尝不是让这门课活得更久一点的因素呢？</p><p>说完了和课程内容设计的第一个问题，我们再来聊聊第二个问题，那就是这门面向产品经理的课，会和其他的大语言模型的相关课程有什么不同？AGI 产品经理究竟应该学什么？</p><h3 id="产品经理究竟应该学什么" tabindex="-1">产品经理究竟应该学什么？ <a class="header-anchor" href="#产品经理究竟应该学什么" aria-label="Permalink to &quot;产品经理究竟应该学什么？&quot;">​</a></h3><p>在我看来，产品经理是链接用户与技术，并且需要为产品商业化负责的这样一批人。</p><p>我们从互联网的成熟期走来，成熟期就意味着：没有技术解决不了的业务问题，产品经理做产品是以需求为驱动力，推动技术实现。也就是：用户要什么，产品经理来做什么。比如用户会说：“我需要一个类似像淘宝一样的小程序…” ，虽然这可能是个玩笑话，但作为一个产品经理，你大约不需要怎么调研就知道这是可行的，你只需要紧跟用户确认需求即可。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/%25E7%25BB%2593%25E6%259D%259F%25E8%25AF%25AD/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/%25E7%25BB%2593%25E6%259D%259F%25E8%25AF%25AD/1.png" alt=""></a></p><p>但在技术早期，用户还不知道技术能干啥。产品经理做产品应该是从技术出发创造挖掘用户的诉求，让用户的诉求逐渐清晰，以技术驱动用户诞生新的诉求。比如 ChatGPT 是在需求还没有明确的情况下被推出来后，才引发用户的广泛使用的。那么，在这个时期，一个产品经理首先应该是理解技术原理的人，其次应该是技术的尝鲜者，然后是需求的试错者。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/%25E7%25BB%2593%25E6%259D%259F%25E8%25AF%25AD/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/%25E7%25BB%2593%25E6%259D%259F%25E8%25AF%25AD/2.png" alt=""></a></p><p>如果此时的产品经理需要了解技术，那么课程内容中就需要有讲解技术原理的部分。但是给产品经理讲的技术不能太深，毕竟我们不是去做算法，研究太深了反倒会失去对品质的要求；但是也不能太浅，否则我们无法体会大语言模型最擅长的东西在哪。</p><p>按照这个要求，我把人工智能 70 年的历史全部捋了一遍，挑选出其中和大语言模型最相关的东西，又加了点“料”，让技术原理课更加有味。因此，你会在课程内看到我使用了大量的比喻、类比来讲述技术原理、预备知识、公式计算，比如 02 节把神经网络类比为一个水流网络、12 节把 Lora 类别为千层饼加酱、15 节和 16 节把不同的部署方式类比为发电站。</p><p>理解技术原理之后，我们定义软件的方式也正在改变，这就需要产品经理深刻理解软件从“规则定义”正在走向“数据定义”时代。所以你也会看到在 02 节、13 节、19 节三处地方都重点讲述了如何构建测试数据、微调数据的方法。而最近一次在 OpenAI 首席产品官和Anthropic 首席产品官的访谈中，他们也提到产品经理最重要的一项技能之一就是“建立评估标准”。</p><p>除此之外，在场景寻找、用户体验、产品形态方面，产品经理都应该保持敏锐的嗅觉感知到AI 在这几方面带来的变化，比如：</p><ul><li><p>场景寻找上：知识场景可以说就是由大语言模型的语言理解能力带来的新场景。</p></li><li><p>用户体验设计上：对话方式的改变也是由大语言模型所带来的。</p></li><li><p>产品形态上：从侧重管理的表格式，也正在向侧重沟通的文本式来变化。</p></li></ul><p>产品经理既然走在产品建设的最前面，就应该是这些新技术、新变化的积极拥抱者。</p><p>不过，在这里我也想叮嘱大家，技术初期的产品经理往往需要带一点孤勇者的精神。因为按照社会发展的第二曲线，新技术在刚刚起步时，往往在各方面比不上旧技术的能力，产品经理首先要克服自己的惯性先把技术用起来，还要鼓动周围的人去使用刚刚起步的新事物。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/%25E7%25BB%2593%25E6%259D%259F%25E8%25AF%25AD/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/%25E7%25BB%2593%25E6%259D%259F%25E8%25AF%25AD/3.png" alt=""></a></p><p>聊完课程设计思路，我也想说说作为一个产品经理我是如何看待这门课程的。</p><h2 id="把课程当做产品来做" tabindex="-1">把课程当做产品来做 <a class="header-anchor" href="#把课程当做产品来做" aria-label="Permalink to &quot;把课程当做产品来做&quot;">​</a></h2><p>“把课程当做产品来做”是我从定下这门课之后就有的想法，那么每一位读者都是产品的用户，每一次的阅读对课程来说都是养料，每一次留言都是反馈，每一次讨论都是注入新的活力。为了记录这些内容，我创建了一个飞书共创文档，在和读者共创的文档里我是这样写的：</p><ul><li><p>和用户共建 Roadmap 是一个构建优秀产品的好方法，历史上有很多伟大的产品，比如亚马逊云、小米都是和用户一起共创而变得伟大，二姐也希望让这门课程本身变成一个带来实在</p></li><li><p>价值、持续优化的好产品！</p></li></ul><p>这个文档我会在课程结束后长期维护，并会链接到课程以外的内容。</p><p>在课程内，我的迭代更新来自于三点：</p><ul><li><p>读者反馈，包括极客时间官方的留言渠道、官方读者群、共创文档里的读者评论和其他友情社群。到我写这门课为止，这些留言总共加起来有 100 多条，我回复的文字总计也有几千字了。我想，这些反馈整理出来又会是一篇好内容了。</p></li><li><p>技术自身的迭代，比如 11 节发布之后，业界又出来了新的解决方法，我会去相应的地方打上补丁。</p></li><li><p>持续的商业运营，将课程放在更广阔的人群里接受考验和磨练。</p></li></ul><p>在课程外，我的迭代更新来自于：</p><ul><li><p>我自己产品的开发经验分享和进展。</p></li><li><p>我看到的优秀的产品、文章的读后感。</p></li><li><p>我自己总结的知识库。</p></li></ul><p>希望这些内容能让这门课弥久常新，也希望它能伴随着各位新晋的 AI 产品经理度过开篇词所说的青铜时代，成为一个“白银级”的 AGI 产品经理！ 祝愿每一位学习这门课程的朋友：</p><ul><li><p>✔︎ 在不确定中看到机遇，</p></li><li><p>✔︎ 在探索中找到方向，</p></li><li><p>✔︎ 在挑战里获得成长，</p></li><li><p>✔︎ 在实践里创造财富。</p></li><li><p>我们，江湖再见！</p></li></ul><p>——产品二姐 2024 年 11 月 13 日</p><p>为了让课程越来越好，我准备了一份结课问卷，希望听到你的真实反馈。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/%25E7%25BB%2593%25E6%259D%259F%25E8%25AF%25AD/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/%25E7%25BB%2593%25E6%259D%259F%25E8%25AF%25AD/4.png" alt=""></a></p>',51)])])}const B=e(a,[["render",n]]);export{u as __pageData,B as default};
